import re

def check_following(response: str) -> bool:
    try:
        percentages = [float(match) for match in re.findall(r'\b\d+(\.\d+)?(?=%)', response)]
        return abs(sum(percentages) - 100) < 1e-6
    except ValueError:
        return False

import json

def check_following(response):
    try:
        recommendations = json.loads(response)
    except json.JSONDecodeError:
        return False

    if not isinstance(recommendations, list):
        return False
    if not (3 <= len(recommendations) <= 5):
        return False

    for item in recommendations:
        if not isinstance(item, dict):
            return False
        if not all(k in item for k in ["category", "recommendation", "potential_savings"]):
            return False
        if not isinstance(item["category"], str):
            return False
        if not isinstance(item["recommendation"], str):
            return False
        if not isinstance(item["potential_savings"], (int, float)):
            return False
    return True

import json

def check_following(response):
    try:
        data = json.loads(response)
    except json.JSONDecodeError:
        return False

    if not isinstance(data, dict) or "budget_analysis" not in data:
        return False

    ba = data["budget_analysis"]
    required_keys = ["total_expenses", "monthly_income", "spending_categories", "recommendations"]

    # Check top-level keys
    if not all(key in ba for key in required_keys):
        return False
    if not isinstance(ba["total_expenses"], (int, float)):
        return False
    if not isinstance(ba["monthly_income"], (int, float)):
        return False

    # Check spending_categories list
    if not isinstance(ba["spending_categories"], list):
        return False
    for item in ba["spending_categories"]:
        if not isinstance(item, dict):
            return False
        if not all(k in item for k in ["category", "amount", "percentage"]):
            return False
        if not isinstance(item["category"], str):
            return False
        if not isinstance(item["amount"], (int, float)):
            return False
        if not isinstance(item["percentage"], (int, float)) or not (0 <= item["percentage"] <= 100):
            return False

    # Check recommendations list
    if not isinstance(ba["recommendations"], list):
        return False
    for rec in ba["recommendations"]:
        if not isinstance(rec, dict):
            return False
        if not all(k in rec for k in ["category", "recommendation", "potential_savings"]):
            return False
        if not isinstance(rec["category"], str):
            return False
        if not isinstance(rec["recommendation"], str):
            return False
        if not isinstance(rec["potential_savings"], (int, float)):
            return False

    return True

