                if not (is_float(plan["total_interest"]) and
                        isinstance(plan["months_to_payoff"], int) and
                        is_float(plan["monthly_payment"])):
                    return False

            # Check recommendations
            if not isinstance(debt["recommendations"], list) or len(debt["recommendations"]) == 0:
                return False
            for rec in debt["recommendations"]:
                if not all(isinstance(rec[k], str) for k in ["title", "description", "impact"]):
                    return False

            return True
        except (KeyError, TypeError):
            return False

    return check_schema(data)

